select energy_manager.load_cards($cards$[
{"id":"p4-b11-031","paper":4,"topic":"Thermal power station performance","kind":"problem","front":"For the coal mill in Example 11.2 (primary air 112.6 TPH at 243 °C, seal air 2 TPH at 50 °C, coal 48.63 TPH, power 351 kW, air-coal mix 161.23 TPH at 65.5 °C, reference 0 °C, Cp 0.24), how much moisture is removed per hour, and what percentage of the coal is that?","back":"About 8,071 kg/h of moisture, which is 16.59% of the coal fed.","explain":"The mill heat balance treats the balance of heat as moisture evaporation. The latent heat of 540 kcal/kg is the book's value for this step and is not restated in the chapter text.","flash":false,"source":"BEE Book 4 Ch 11 p213","steps":[{"prompt":"Total heat input: primary air, seal air and mill power.","answer":"PA: 112,600 × 0.24 × 243 = 6,566,832 kcal/h. Seal air: 2,000 × 0.24 × 50 = 24,000 kcal/h. Power: 351 × 860 = 301,860 kcal/h. Total = 6,892,692 kcal/h.","explain":"Power is converted to heat at 860 kcal per kWh so every stream is on one heat basis."},{"prompt":"Heat output as sensible heat of the air-coal mix.","answer":"161,230 × 0.24 × 65.5 = 2,534,536 kcal/h.","explain":"Mix flow in kg/h times specific heat times temperature rise above the 0 °C reference."},{"prompt":"Heat carried away by moisture, by difference.","answer":"6,892,692 − 2,534,536 = 4,358,156 kcal/h.","explain":"The heat not accounted for in the mix goes into evaporating the moisture."},{"prompt":"Moisture evaporated per hour.","answer":"4,358,156 ÷ 540 = 8,071 kg/h.","explain":"Dividing heat by the latent heat of 540 kcal/kg gives the moisture mass."},{"prompt":"Percentage moisture removed.","answer":"8,071 ÷ 48,630 × 100 = 16.59%.","explain":"Expressed on the coal feed rate, this is the share of coal mass that is water driven off in the mill."}],"order":4481},
{"id":"p4-b11-032","paper":4,"topic":"Thermal power station performance","kind":"problem","front":"Economiser and APH data: feed water 609 TPH, FW 244 → 274 °C, gas 473 → 379 °C in the economiser; APH air 110 TPH from 35 → 354 °C, APH gas 379 → 146 °C. Find economiser effectiveness, economiser heat pick-up, APH effectiveness and APH heat pick-up.","back":"Economiser effectiveness 13.1%; economiser heat pick-up 18,270 MCal/h; APH effectiveness 92.7%; APH heat pick-up 8,422 MCal/h.","explain":"Effectiveness shows how much of the available temperature difference the exchanger uses. Heat pick-up is the heat absorbed on the working fluid side.","flash":false,"source":"BEE Book 4 Ch 11 p215","steps":[{"prompt":"Economiser effectiveness.","answer":"(274 − 244) ÷ (473 − 244) = 30 ÷ 229 = 13.1%.","explain":"Denominator is the maximum possible rise: gas inlet temperature minus feed water inlet temperature."},{"prompt":"Economiser heat pick-up.","answer":"609,000 × 1 × (274 − 244) = 18,270,000 kcal/h = 18,270 MCal/h.","explain":"Feed water flow in kg/h times specific heat (1) times temperature rise."},{"prompt":"APH effectiveness.","answer":"(354 − 35) ÷ (379 − 35) = 319 ÷ 344 = 92.7%.","explain":"Air temperature rise over the maximum possible rise, which is gas inlet minus air inlet temperature."},{"prompt":"APH heat pick-up.","answer":"110,000 × 0.24 × (354 − 35) = 8,422 MCal/h.","explain":"Air flow in kg/h times specific heat of air (0.24) times air temperature rise."}],"order":4482},
{"id":"p4-b11-033","paper":4,"topic":"Thermal power station performance","kind":"problem","front":"An LP heater has shell saturation temperature 86.5 °C, feed water entering at 47 °C and leaving at 77.5 °C, and drain outlet at 61.8 °C. Find the TTD and DCA.","back":"TTD = 9 °C. DCA = 14.8 °C.","explain":"A TTD of 9 °C is the gap between the steam saturation temperature and the feed water leaving. DCA compares the drain leaving with the feed water entering.","flash":false,"source":"BEE Book 4 Ch 11 p219","steps":[{"prompt":"Identify the reference temperature for TTD.","answer":"Saturation temperature at the shell (inlet steam) pressure = 86.5 °C.","explain":"TTD is always measured against the saturation temperature of the inlet steam, not the feed water inlet."},{"prompt":"Compute TTD.","answer":"86.5 − 77.5 = 9 °C.","explain":"Saturation temperature minus feed water outlet temperature."},{"prompt":"Compute DCA.","answer":"61.8 − 47 = 14.8 °C.","explain":"Drain outlet temperature minus feed water inlet temperature. A lower DCA means better heat recovery."},{"prompt":"Judge the result against design.","answer":"Compare with design TTD and DCA; higher values indicate reduced heat transfer, mainly from fouling.","explain":"The chapter treats increases in these values as a sign of lost heat transfer."}],"order":4483},
{"id":"p4-b11-034","paper":4,"topic":"Thermal power station performance","kind":"problem","front":"A 210 MW reheat unit has main steam flow 627 TPH (enthalpy 814.8 kcal/kg), feed water enthalpy 244 kcal/kg, reheat flow 565 TPH (cold reheat 733.3 kcal/kg, hot reheat 844.3 kcal/kg) and boiler efficiency 87%. Find turbine heat rate, unit heat rate and turbine cycle efficiency.","back":"Turbine heat rate ≈ 2003 kcal/kWh. Unit heat rate ≈ 2302 kcal/kWh. Turbine cycle efficiency ≈ 42.9%.","explain":"Turbine heat rate counts heat added by both main and reheat steam. Unit heat rate adds the boiler losses on top.","flash":false,"source":"BEE Book 4 Ch 11 p221","steps":[{"prompt":"Heat added by main steam.","answer":"627,000 × (814.8 − 244) = 357,891,600 kcal/h.","explain":"Main steam flow times enthalpy rise from feed water to main steam."},{"prompt":"Heat added by reheat.","answer":"565,000 × (844.3 − 733.3) = 62,715,000 kcal/h.","explain":"Reheat flow times the enthalpy rise between cold and hot reheat."},{"prompt":"Turbine heat rate.","answer":"(357,891,600 + 62,715,000) ÷ 210,000 kW = 2003 kcal/kWh.","explain":"Total heat input to the turbine divided by generator output."},{"prompt":"Unit heat rate.","answer":"2003 ÷ 0.87 = 2302 kcal/kWh.","explain":"Dividing by boiler efficiency accounts for boiler losses."},{"prompt":"Turbine cycle efficiency.","answer":"860 ÷ 2003 × 100 = 42.9%.","explain":"Efficiency is the reciprocal of heat rate in consistent units."}],"order":4484},
{"id":"p4-b11-035","paper":4,"topic":"Thermal power station performance","kind":"problem","front":"A small biomass plant has turbine inlet steam at 66 kg/cm² (g) and 480 °C (enthalpy 804.4 kcal/kg), exhaust at 0.18 kg/cm² (a), stage efficiency 85%, boiler efficiency 71% on bagasse GCV 2276 kcal/kg, maximum steam 80 TPH, mechanical efficiency 0.985, generator 0.95 and gearbox 0.98. Find steam per tonne of bagasse, bagasse for 80 TPH, specific steam consumption and power.","back":"2.16 t steam per t bagasse. 37.03 t/h bagasse for 80 TPH. Specific steam consumption 4.0 kg/kWh. Power 20 MW.","explain":"Stage efficiency reduces the usable enthalpy drop, which sets the steam rate. Mechanical, generator and gearbox efficiencies then convert turbine work to electrical output.","flash":false,"source":"BEE Book 4 Ch 11 p223","steps":[{"prompt":"Actual exhaust enthalpy and enthalpy drop.","answer":"H2 = 804.4 − 0.85 × (804.4 − 528.8) = 570.1 kcal/kg. Actual drop = 804.4 − 570.1 = 234.3 kcal/kg.","explain":"Stage efficiency takes only 85% of the isentropic drop as useful work."},{"prompt":"Check dryness at turbine exhaust.","answer":"57.38 + 564.6 × X = 570.1, so X ≈ 0.90. This is above the 88% dryness requirement.","explain":"Exhaust enthalpy = hf + X × hfg at 0.18 ata. The book's values 57.38 and 564.6 are used here."},{"prompt":"Steam generated per tonne of bagasse.","answer":"0.71 × 2276 ÷ (804.4 − 57.38) = 2.16 t of steam per t of bagasse.","explain":"Boiler efficiency times fuel GCV gives heat delivered; dividing by the heat per kg of steam gives steam per kg of fuel."},{"prompt":"Bagasse needed for 80 TPH of steam.","answer":"80 ÷ 2.16 = 37.03 t/h.","explain":"Fuel rate scales directly with steam demand."},{"prompt":"Specific steam consumption.","answer":"860 ÷ [(804.4 − 570.1) × 0.985 × 0.95 × 0.98] = 860 ÷ (234.3 × 0.917) = 4.0 kg/kWh.","explain":"The 0.917 combines mechanical, generator and gearbox efficiencies."},{"prompt":"Power generated by 80 TPH.","answer":"80,000 ÷ 4.0 = 20,000 kW = 20 MW.","explain":"Steam flow divided by specific steam consumption gives power."}],"order":4485},
{"id":"p4-b11-036","paper":4,"topic":"Thermal power station performance","kind":"problem","front":"The condenser back pressure is 0.1 ata and atmospheric pressure is 752 mmHg. What is the condenser vacuum?","back":"676 mmHg.","explain":"Vacuum is measured against atmosphere, so it is atmospheric pressure minus the absolute back pressure.","flash":false,"source":"BEE Book 4 Ch 11 p229","steps":[{"prompt":"Convert back pressure to mmHg.","answer":"0.1 × 760 = 76 mmHg.","explain":"1 ata = 760 mmHg."},{"prompt":"Subtract back pressure from atmospheric pressure.","answer":"752 − 76 = 676 mmHg.","explain":"Vacuum = atmospheric pressure − condenser back pressure."},{"prompt":"Interpret the result.","answer":"A vacuum of 676 mmHg means the absolute pressure in the condenser is 76 mmHg.","explain":"Both numbers describe the same condition, one relative to atmosphere and one absolute."}],"order":4486},
{"id":"p4-b11-037","paper":4,"topic":"Thermal power station performance","kind":"problem","front":"The exhaust pressure of a turbine is 0.051 kg/cm² (a). With atmospheric pressure of 760 mmHg, find the condenser vacuum in millibar.","back":"About 722.5 mmHg, or about 963 millibar (book: 963.24).","explain":"Pressures are converted to mmHg first, then to millibar using 1.01325 bar = 760 mmHg.","flash":false,"source":"BEE Book 4 Ch 11 p230","steps":[{"prompt":"Back pressure in mmHg.","answer":"760 × 0.051 ÷ 1.0332 = 37.51 mmHg.","explain":"1.0332 kg/cm² = 760 mmHg."},{"prompt":"Vacuum in mmHg.","answer":"760 − 37.51 = 722.49 mmHg.","explain":"Atmospheric pressure minus absolute back pressure."},{"prompt":"Vacuum in millibar.","answer":"1.01325 × 722.49 ÷ 760 = 963.2 mbar.","explain":"Converts mmHg to bar using 760 mmHg = 1.01325 bar."}],"order":4487},
{"id":"p4-b11-038","paper":4,"topic":"Thermal power station performance","kind":"problem","front":"A turbine's condenser back pressure is 0.11 bar (a) and atmospheric pressure is 755 mmHg. Find the condenser vacuum in millibar.","back":"672.5 mmHg, or about 896.6 millibar.","explain":"The same mmHg route applies: convert back pressure to mmHg, subtract from atmosphere, then convert the vacuum to millibar.","flash":false,"source":"BEE Book 4 Ch 11 p230","steps":[{"prompt":"Back pressure in mmHg.","answer":"760 × 0.11 ÷ 1.01325 = 82.5 mmHg.","explain":"1 bar(a) = 760 ÷ 1.01325 mmHg, so bar converts through the atmosphere ratio."},{"prompt":"Vacuum in mmHg.","answer":"755 − 82.5 = 672.5 mmHg.","explain":"Atmospheric pressure minus back pressure."},{"prompt":"Vacuum in millibar.","answer":"1.01325 × 672.5 ÷ 760 = 896.6 mbar.","explain":"Converts the mmHg vacuum back to bar using 760 mmHg = 1.01325 bar."}],"order":4488},
{"id":"p4-b11-039","paper":4,"topic":"Thermal power station performance","kind":"problem","front":"A steam plant shows a condenser vacuum of 700 mmHg with atmospheric pressure of 740 mmHg. Find the absolute pressure in the condenser in kg/cm² (a).","back":"40 mmHg absolute, which is about 0.0544 kg/cm² (a).","explain":"Vacuum is relative to atmosphere, so absolute pressure is atmospheric pressure minus vacuum.","flash":false,"source":"BEE Book 4 Ch 11 p230","steps":[{"prompt":"Absolute pressure in mmHg.","answer":"740 − 700 = 40 mmHg.","explain":"Absolute = atmospheric − vacuum."},{"prompt":"Convert to kg/cm² (a).","answer":"40 ÷ 760 × 1.0332 = 0.0544 kg/cm² (a).","explain":"760 mmHg = 1.0332 kg/cm² (a)."},{"prompt":"Check the direction of the subtraction.","answer":"Absolute pressure is always below atmospheric when there is vacuum, so 40 mmHg is consistent.","explain":"A quick sense-check avoids swapping the two terms."}],"order":4489},
{"id":"p4-b11-040","paper":4,"topic":"Thermal power station performance","kind":"problem","front":"Cooling water enters a condenser at 30 °C and leaves at 39 °C. Vacuum is 684 mmHg and atmospheric pressure is 750 mmHg. Find the condenser effectiveness and TTD.","back":"Effectiveness ≈ 67.7%. TTD ≈ 4.3 °C.","explain":"The saturation temperature comes from steam tables at the back pressure, which the book gives as 43.3 °C. That table value is not in the chapter text.","flash":false,"source":"BEE Book 4 Ch 11 p231","steps":[{"prompt":"Find the back pressure.","answer":"750 − 684 = 66 mmHg, i.e. 66 ÷ 760 × 1.0332 = 0.0897 kg/cm² (a).","explain":"Back pressure = atmospheric − vacuum, converted to kg/cm²."},{"prompt":"Find the saturation temperature at this pressure.","answer":"43.3 °C (steam-table value quoted in the book).","explain":"Look up Tsat for 0.0897 kg/cm² (a) in steam tables."},{"prompt":"Condenser effectiveness.","answer":"(39 − 30) ÷ (43.3 − 30) × 100 = 9 ÷ 13.3 × 100 = 67.7%.","explain":"Actual cooling water rise over the maximum possible rise."},{"prompt":"Condenser TTD.","answer":"TTD = Tsat − Tcwo = 43.3 − 39 = 4.3 °C.","explain":"A small TTD means good heat transfer in the condenser."}],"order":4490},
{"id":"p4-b11-041","paper":4,"topic":"Thermal power station performance","kind":"problem","front":"A 210 MW turbine condenser receives 560 T/h of exhaust steam at 0.1042 bar (a) and 88% dryness, with cooling water rising from 30 °C to 40 °C. Find the condenser heat load and the cooling water flow required.","back":"Heat load ≈ 1,178,240,000 kJ/h. Cooling water flow ≈ 28,188 T/h.","explain":"Heat load is steam flow times latent heat of the wet steam. The cooling water must absorb the same heat over its temperature rise.","flash":false,"source":"BEE Book 4 Ch 11 p231","steps":[{"prompt":"Latent heat of the wet steam.","answer":"Latent heat at 0.1042 bar (a) = 2391 kJ/kg (steam table). For 88% dry steam: 2391 × 0.88 = 2104 kJ/kg.","explain":"Only the vapour fraction releases latent heat on condensing."},{"prompt":"Condenser heat load.","answer":"560 × 1000 × 2104 = 1,178,240,000 kJ/h.","explain":"Steam flow in kg/h times latent heat per kg."},{"prompt":"Cooling water flow from heat balance.","answer":"1,178,240,000 ÷ 4.18 = Q × 1 × (40 − 30), so Q = 28,187,600 kg/h ≈ 28,188 T/h.","explain":"Division by 4.18 converts kJ to kcal, since Cp is in kcal/kg °C."}],"order":4491},
{"id":"p4-b11-042","paper":4,"topic":"Thermal power station performance","kind":"problem","front":"A captive plant delivers 29 MW at the generator (96% generator efficiency, 1100 kW gearbox loss). Steam at 105 ata and 485 °C (795 kcal/kg) expands to 0.1 ata with 0.9 dryness (dry-saturated enthalpy 618 kcal/kg at 0.1 ata). Feed water enters at 105 °C (105 kcal/kg) and boiler efficiency is 86%. Find turbine output, steam flow, turbine heat rate and unit heat rate.","back":"Turbine output ≈ 31,308 kW. Steam flow ≈ 115 TPH. Turbine heat rate ≈ 2736 kcal/kWh. Unit heat rate ≈ 3182 kcal/kWh.","explain":"Work back from generator output through the generator and gearbox losses to find turbine output. Then heat rate follows from steam flow and the enthalpy rise.","flash":false,"source":"BEE Book 4 Ch 11 p232","steps":[{"prompt":"Exhaust enthalpy.","answer":"h2 = 45.5 + 0.9 × (618 − 45.5) = 560.75 kcal/kg.","explain":"Wet steam enthalpy = water enthalpy + dryness × latent heat, using the 0.1 ata values from the example."},{"prompt":"Turbine output.","answer":"Generator input = 29,000 ÷ 0.96 = 30,208 kW. Add 1,100 kW gearbox loss gives 31,308 kW.","explain":"The gearbox sits between turbine and generator, so its loss is added back to get turbine output."},{"prompt":"Steam flow through the turbine.","answer":"31,308 × 860 ÷ (795 − 560.75) = 114,941 kg/h ≈ 115 TPH.","explain":"Turbine output in kcal/h divided by enthalpy drop per kg."},{"prompt":"Turbine heat rate.","answer":"115,000 × (795 − 105) ÷ 29,000 = 2736 kcal/kWh.","explain":"Heat input to the turbine per kWh of generator output."},{"prompt":"Unit heat rate.","answer":"2736 ÷ 0.86 = 3182 kcal/kWh.","explain":"Dividing by boiler efficiency adds boiler losses to the turbine heat rate."}],"order":4492},
{"id":"p4-b11-043","paper":4,"topic":"Thermal power station performance","kind":"problem","front":"If a power plant's heat rate is 2900 kcal/kWh, what is its efficiency?","back":"About 29.7%.","explain":"Efficiency is the reciprocal of heat rate in consistent units, using 860 kcal per kWh.","flash":false,"source":"BEE Book 4 Ch 11 p234","steps":[{"prompt":"Recall the energy equivalence.","answer":"1 kWh = 860 kcal.","explain":"This converts electrical output into the same unit as heat input."},{"prompt":"Compute efficiency.","answer":"860 ÷ 2900 × 100 = 29.66%.","explain":"Output heat equivalent divided by heat input."},{"prompt":"Round for the answer.","answer":"About 29.7%.","explain":"Quote one decimal place for exam answers."}],"order":4493},
{"id":"p4-b12-001","paper":4,"topic":"Steel sector performance","kind":"fact","front":"How much of Indian industry's electricity and coal does the iron and steel sector use, and how much of its production cost is energy?","back":"About 10% of electricity and 27% of coal used by Indian industry. Energy is about 30–35% of the sector's production cost.","explain":"The chapter calls iron and steel the largest energy consumer among all industrial sectors. Energy cost is therefore the main lever for steel production cost.","flash":true,"source":"BEE Book 4 Ch 12 p237","order":4494},
{"id":"p4-b12-002","paper":4,"topic":"Steel sector performance","kind":"fact","front":"What are the two main routes for steel production?","back":"The primary route makes steel from iron ore and scrap via blast furnace and BOF or OHF. The secondary route makes steel from sponge iron and scrap in an electric arc furnace (EAF).","explain":"The secondary route skips coke making and pig iron production, which is why it uses much less energy.","flash":false,"source":"BEE Book 4 Ch 12 p237","order":4495},
{"id":"p4-b12-003","paper":4,"topic":"Steel sector performance","kind":"fact","front":"What are the four basic steps of the primary (integrated) steel process?","back":"Material preparation (coke and sinter or pellets); iron making in the blast furnace; steel making by processing molten iron; and steel forming and finishing.","explain":"Each step has its own energy profile, and the blast furnace stage dominates energy use.","flash":false,"source":"BEE Book 4 Ch 12 p238","order":4496},
{"id":"p4-b12-004","paper":4,"topic":"Steel sector performance","kind":"fact","front":"Which process is the largest energy consumer in primary steel making?","back":"Reduction of iron ore in the blast furnace.","explain":"Coking, sinter making and the blast furnace together take about 61.3% of total energy in a typical plant (Table 12.2), so iron making is the main target for energy audits.","flash":true,"source":"BEE Book 4 Ch 12 p238","order":4497},
{"id":"p4-b12-005","paper":4,"topic":"Steel sector performance","kind":"fact","front":"Why is the BOF route preferred over the open hearth furnace (OHF) for steel making?","back":"BOF gives greater productivity and lower capital cost, needs no net energy input, and can even export energy as BOF gas and steam. OHF uses more energy but can take in more scrap.","explain":"The chapter says BOF is rapidly replacing OHF worldwide. It operates by injecting oxygen to oxidise the carbon in the hot metal.","flash":false,"source":"BEE Book 4 Ch 12 p237","order":4498},
{"id":"p4-b12-006","paper":4,"topic":"Steel sector performance","kind":"fact","front":"What happens to the volatile compounds driven off during coke making?","back":"They are collected and processed to recover combustible gases and other by-products. The solid carbon left in the sealed, heated oven is coke.","explain":"Coal is coked in a sealed oven heated without oxygen. The coke is then quenched, wet or dry, before going to the blast furnace.","flash":false,"source":"BEE Book 4 Ch 12 p239","order":4499},
{"id":"p4-b12-007","paper":4,"topic":"Steel sector performance","kind":"fact","front":"At what temperatures do the plastic, tar-evolution and coke stabilisation stages occur in a coke oven?","back":"Plastic stage 375–475 °C; tar evolution and resolidification to semi-coke 475–600 °C; coke stabilisation from about 600 °C to 1100 °C.","explain":"During the plastic stage, the layers move toward the oven centre and build up gas pressure on the heating walls.","flash":false,"source":"BEE Book 4 Ch 12 p240","order":4500},
{"id":"p4-b12-008","paper":4,"topic":"Steel sector performance","kind":"fact","front":"Why is sinter preferred as blast furnace burden material?","back":"It makes use of ore fines, coke breeze and metallurgical wastes. It gives better reducibility, raises blast furnace productivity, improves hot metal quality and reduces coke rate.","explain":"Sintering agglomerates iron ore fines into a usable burden. The process was developed in the early 20th century to treat waste fines.","flash":false,"source":"BEE Book 4 Ch 12 p240","order":4501},
{"id":"p4-b12-009","paper":4,"topic":"Steel sector performance","kind":"fact","front":"What are the raw materials of a sinter plant, and what sizes are used?","back":"Iron ore fines (−10 mm), coke breeze (−3 mm), limestone and dolomite fines (−3 mm), and other metallurgical wastes.","explain":"The mix is moistened in a drum and loaded onto the moving grate. The top surface is ignited by stationary burners at about 1200 °C.","flash":false,"source":"BEE Book 4 Ch 12 p241","order":4502},
{"id":"p4-b12-010","paper":4,"topic":"Steel sector performance","kind":"fact","front":"What happens to sinter after it is cooled and screened?","back":"Sinter of +6 mm goes to the blast furnace, and −6 mm is recirculated as return sinter.","explain":"Return fines go back into the sinter mix, so the process recycles fine material instead of losing it.","flash":true,"source":"BEE Book 4 Ch 12 p241","order":4503},
{"id":"p4-b12-011","paper":4,"topic":"Steel sector performance","kind":"fact","front":"At what temperatures do the iron oxide reduction reactions by CO begin in the blast furnace?","back":"3Fe₂O₃ + CO → 2Fe₃O₄ + CO₂ from 450 °C. Fe₃O₄ + CO → 3FeO + CO₂ from 600 °C. FeO + CO → Fe + CO₂ from 700 °C.","explain":"The second equation is Fe₃O₄ in the chapter (the OCR reads it as Fe₂O₃). The reduction proceeds stepwise from higher to lower oxides.","flash":false,"source":"BEE Book 4 Ch 12 p242","order":4504},
{"id":"p4-b12-012","paper":4,"topic":"Steel sector performance","kind":"fact","front":"What two roles does coke play in the blast furnace?","back":"It is the reductant for the iron oxides (through CO produced from CO₂ and carbon) and the source of thermal energy, burning with hot blast to produce heat.","explain":"Coke burns with the hot blast (C + O₂ → CO₂ + heat), and CO₂ reacts with excess carbon to form CO (CO₂ + C → 2CO), which reduces the ore.","flash":false,"source":"BEE Book 4 Ch 12 p242","order":4505},
{"id":"p4-b12-013","paper":4,"topic":"Steel sector performance","kind":"fact","front":"What reaction removes sulphur from the iron in the blast furnace, and at what temperature does limestone start to decompose?","back":"FeS + CaO + C → CaS + FeO + C, with the CaS going into the slag. Limestone decomposes by CaCO₃ → CaO + CO₂, starting at about 875 °C.","explain":"The CaO from limestone removes sulphur, and the CaS floats in the slag on top of the liquid iron because the slag is less dense.","flash":false,"source":"BEE Book 4 Ch 12 p242","order":4506},
{"id":"p4-b12-014","paper":4,"topic":"Steel sector performance","kind":"fact","front":"How is blast furnace top gas used?","back":"It is burned in hot blast stoves to preheat the air entering the furnace. Any surplus goes to the boiler house to make steam for a turbo blower that supplies the cold blast.","explain":"The gas has considerable energy value, so it is used as a fuel rather than vented. The blast furnace itself is a counter-current reactor, with solids descending and gases rising.","flash":false,"source":"BEE Book 4 Ch 12 p243","order":4507},
{"id":"p4-b12-015","paper":4,"topic":"Steel sector performance","kind":"fact","front":"What temperature occurs at the centre of the reaction in a BOF, and when is the sample taken?","back":"Around 2000–2500 °C at the centre of reaction. A sample is taken after blowing for 16–18 minutes and temperature is measured by thermocouple.","explain":"Carbon monoxide evolving during refining stirs the bath, and refining ends when the desired carbon content is reached.","flash":false,"source":"BEE Book 4 Ch 12 p243","order":4508},
{"id":"p4-b12-016","paper":4,"topic":"Steel sector performance","kind":"fact","front":"What share of world liquid steel is cast by continuous casting, and what are its main advantages?","back":"More than 60% of total liquid steel. Advantages are higher yield, lower energy consumption, and elimination of primary mills.","explain":"In continuous casting the liquid steel passes through a tundish into a water-cooled copper mould, which shapes the steel as it solidifies.","flash":true,"source":"BEE Book 4 Ch 12 p244","order":4509},
{"id":"p4-b12-017","paper":4,"topic":"Steel sector performance","kind":"fact","front":"What is near-net-shape casting, and what does it reduce?","back":"Casting products closer to their final shape, which reduces the need for hot rolling.","explain":"Less rolling means less reheating and fewer rolling-stage energy inputs for the same finished product.","flash":false,"source":"BEE Book 4 Ch 12 p245","order":4510},
{"id":"p4-b12-018","paper":4,"topic":"Steel sector performance","kind":"fact","front":"What is the specific energy consumption range of Indian steel plants, and how does it compare with the world level?","back":"6.17 to 8 Gcal per tonne of crude steel (tcs). The world level is 4.5 Gcal/tcs.","explain":"Variation between plants comes from different processes, coal quality, product types and energy efficiency measures adopted.","flash":true,"source":"BEE Book 4 Ch 12 p245","order":4511},
{"id":"p4-b12-019","paper":4,"topic":"Steel sector performance","kind":"fact","front":"Which plant in Table 12.1 had the highest specific energy consumption in 2008-09?","back":"IISCO Steel Plant, at 8.27 Gcal/tcs. Bhilai and Durgapur were lowest at 6.50 Gcal/tcs.","explain":"The table is sourced from the Joint Plant Committee, Government of India.","flash":false,"source":"BEE Book 4 Ch 12 p245","order":4512},
{"id":"p4-b12-020","paper":4,"topic":"Steel sector performance","kind":"fact","front":"What share of total energy do coking, sinter making and the blast furnace together consume in a typical steel plant?","back":"About 61.3% (iron making). Slabbing, hot strip and cold rolling mills together account for about 36.5%.","explain":"Table 12.2 gives the energy per tonne of crude steel for each process, and these shares follow from it.","flash":false,"source":"BEE Book 4 Ch 12 p246","order":4513},
{"id":"p4-b12-021","paper":4,"topic":"Steel sector performance","kind":"fact","front":"Why does EAF steel making use much less energy than the integrated route?","back":"Coke production, pig iron production and the primary steel steps are omitted. Scrap is melted and refined with a strong electric current.","explain":"Because the energy-heavy ironmaking steps are skipped, the route consumes far less energy per tonne of steel.","flash":false,"source":"BEE Book 4 Ch 12 p246","order":4514},
{"id":"p4-b12-022","paper":4,"topic":"Steel sector performance","kind":"fact","front":"What share of total EAF energy is electrical, and what is the rest?","back":"About 60–65% is electrical. The remaining 35–40% is chemical, from oxidation of carbon, iron and silicon and from burning natural gas with oxy-fuel burners.","explain":"The balance depends on the melt shop operation. Chemical energy from oxidation adds to the electrical input.","flash":false,"source":"BEE Book 4 Ch 12 p247","order":4515},
{"id":"p4-b12-023","paper":4,"topic":"Steel sector performance","kind":"fact","front":"About what share of total EAF energy leaves in the liquid steel?","back":"About 53%. The rest is lost to the slag, waste gas and cooling.","explain":"The Sankey diagram labels (Figure 12.9) are garbled in the OCR, so this figure relies on the chapter text.","flash":false,"source":"BEE Book 4 Ch 12 p247","order":4516},
{"id":"p4-b12-024","paper":4,"topic":"Steel sector performance","kind":"fact","front":"What roles do oxygen blowing and the carbon monoxide it produces play in an EAF heat?","back":"Oxidising carbon is an important energy source. The CO produced helps flush nitrogen and hydrogen out of the metal and foams the slag, which reduces heat loss and shields the arc.","explain":"The foamy slag shields the arc, which reduces damage to the refractories.","flash":false,"source":"BEE Book 4 Ch 12 p247","order":4517},
{"id":"p4-b12-025","paper":4,"topic":"Steel sector performance","kind":"fact","front":"What are the raw materials for secondary steel making in an electric arc furnace?","back":"Sponge iron (direct reduced iron, DRI) and steel scrap.","explain":"DRI is produced by reducing ore below its melting point, and it has different properties from pig iron.","flash":true,"source":"BEE Book 4 Ch 12 p237","order":4518}
